cd /tmp && node -e "
const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    executablePath: '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-gpu', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setViewport({width: 1400, height: 3000});
  await page.goto('http://localhost:8899/%E4%B8%8A%E6%B5%B7%E8%81%8C%E5%8A%A1%E7%A7%91%E6%8A%80%E6%88%90%E6%9E%9C%E8%B5%8B%E6%9D%83%E5%88%86%E6%9E%90%E6%8A%A5%E5%91%8A.html', {
    waitUntil: 'networkidle0',
    timeout: 30000
  });
  console.log('Page loaded');
  await new Promise(r => setTimeout(r, 5000));
  await page.screenshot({path: '/workspace/screenshot_full.png', fullPage: true});
  console.log('Screenshot saved!');
  await browser.close();
})().catch(e => { console.error('Error:', e.message); process.exit(1); });
" 2>&1
